{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw, ImageOps
im = Image.open('radiograph.jpg').convert('L')
regions = {'g_lower_right': (480, 550, 1300, 1000, 2),
           'g_lower_left' : (1280, 550, 1850, 1020, 2),
           'g_upper_right': (550, 300, 1200, 650, 2),
           'g_upper_left' : (1300, 280, 1900, 600, 2)}
for name,(x1,y1,x2,y2,f) in regions.items():
    c = im.crop((x1,y1,x2,y2)).resize(((x2-x1)*f,(y2-y1)*f), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for x in range(x1, x2+1, 50):
        if x % 100 == 0:
            d.line([((x-x1)*f,0),((x-x1)*f,(y2-y1)*f)], fill=255, width=1)
            d.text(((x-x1)*f+2,2), str(x), fill=255)
        else:
            d.line([((x-x1)*f,0),((x-x1)*f,(y2-y1)*f)], fill=90, width=1)
    for y in range(y1, y2+1, 50):
        if y % 100 == 0:
            d.line([(0,(y-y1)*f),((x2-x1)*f,(y-y1)*f)], fill=255, width=1)
            d.text((2,(y-y1)*f+2), str(y), fill=255)
        else:
            d.line([(0,(y-y1)*f),((x2-x1)*f,(y-y1)*f)], fill=90, width=1)
    c.save(f'/tmp/{name}.png')
    print(name, c.size)
EOF", "description": "Create fine-grid zoomed crops of all posterior segments"}

